+export function positiveSum(values: number[]): number {
+  let total = 0;
+  for (let i = 0; i < values.length - 1; i++) {
+    if (values[i] > 0) total += values[i];
+  }
+  return total;
+}
+
+export function fixtureBranchLabel(): string {
+  return "main-oracle";
+}
